func formatZZ9_9(d decimal.Decimal) string {
	// ZZ9.9 width 5
	d = truncDecimal(d, 1)
	sign := ""
	if d.IsNegative() {
		sign = "-"
		d = d.Neg()
	}
	s := d.StringFixed(1) // e.g. "40.0"
	parts := strings.Split(s, ".")
	intPart := parts[0]
	fracPart := parts[1]
	// int part width 3, Z Z 9
	intPart = fmt.Sprintf("%03s", intPart)
	// if more than 3 digits, drop high order
	if len(intPart) > 3 {
		intPart = intPart[len(intPart)-3:]
	}
	formatted := ""
	for i := 0; i < 3; i++ {
		ch := intPart[i]
		if i < 2 {
			if isAllZero(intPart[:i+1]) && ch == '0' {
				// check if all leading up to here are zero and not last required 9?
				// For ZZ9, last char always digit
				// Determine if intPart as number is zero? But we need to suppress leading zeros
				// Simpler: suppress if prefix up to i is all zeros and we are not at last pos (2)
				// Actually need to look at whether the whole int value's leading digits are zero.
				// Use: if the integer formed by intPart has leading zeros, replace with space
				// We have intPart padded to 3, so suppress zeros before last non-zero
				// Approach: find first non-zero; everything before last position that is zero before it -> space
				formatted += " "
			} else {
				// need to check if all chars up to last non-zero? Let's do proper
				formatted += string(ch)
			}
		} else {
			formatted += string(ch)
		}
	}
	// Proper Z suppression: replace leading zeros with spaces until last digit before decimal
	// Recompute correctly
	intVal := d.IntPart() // truncated integer part
	intStr := fmt.Sprintf("%d", intVal)
	if len(intStr) > 3 {
		intStr = intStr[len(intStr)-3:]
	}
	// Build with Z logic
	padded := fmt.Sprintf("%3s", intStr)
	// Now replace leading zeros that are padding zeros? But intStr already without leading zeros except "0"
	// For ZZ9, we want e.g. 0 -> "  0", 5 -> "  5", 40 -> " 40", 100 -> "100"
	// So we can just right-align intStr in width 3
	intFormatted := fmt.Sprintf("%3s", intStr)
	// However if intStr is "0", we want "  0" which fmt gives.
	formattedInt := intFormatted
	result := formattedInt + "." + fracPart
	_ = formatted
	_ = sign
	if sign != "" {
		// COBOL would handle sign separately; not needed for this program (positive)
		// Place sign at leftmost?
		result = sign + result[1:]
	}
	return result
