func formatNumericEdited(d decimal.Decimal, intDigits int, scale int, withCommas bool) string {
	// Truncate to scale (MOVE truncates)
	d = truncDecimal(d, int32(scale))
	neg := d.IsNegative()
	if neg {
		d = d.Neg()
	}
	s := d.StringFixed(int32(scale))
	parts := strings.Split(s, ".")
	intPart := "0"
	fracPart := ""
	if len(parts) == 1 {
		intPart = parts[0]
	} else {
		intPart = parts[0]
		fracPart = parts[1]
	}
	// Drop high order digits if overflow
	if len(intPart) > intDigits {
		intPart = intPart[len(intPart)-intDigits:]
	}
	// Build integer formatted with commas and Z suppression
	// Width = intDigits, last digit is 9 (always shown), others Z
	// Commas are inside suppressed zone -> become spaces if suppression
	// Build base int string right-aligned in intDigits
	intStrNoPad := intPart
	// Remove leading zeros for determining suppression, but keep at least one digit
	trimmed := strings.TrimLeft(intStrNoPad, "0")
	if trimmed == "" {
		trimmed = "0"
	}
	// Right align trimmed in intDigits
	intFormatted := fmt.Sprintf("%*s", intDigits, trimmed)
	// Now insert commas if needed
	if withCommas {
		// intDigits determines comma positions from right: every 3 digits
		// For widths like 9, 10 etc., commas at positions
		// We have intFormatted of length intDigits, with leading spaces
		// Insert commas at every 3 from right
		chars := []rune(intFormatted)
		// Determine comma insertion points: from right, every 3
		// But commas occupy a position in picture. So intDigits includes comma positions? No
		// In COBOL picture Z,ZZZ,ZZ9 etc., commas are extra chars beyond digit count?
		// Actually picture len includes commas and dot.
		// Our intDigits is number of digit positions (Z+9). Commas are separate.
		// So final integer part with commas has length > intDigits.
		// Need to construct with commas.
		// Example: PIC Z,ZZZ,ZZ9.99 has 7 digit positions, picture len 12 (7 digits +2 commas+ dot +2 decimals)
		// So we need to format digit string with commas, then apply Z suppression where commas in suppressed zone become spaces.
		// Approach: build digit string padded to intDigits with leading zeros? No with spaces then handle.
		// Simpler: build full comma string for the number using trimmed or padded?
		// We need to create a digit string of length intDigits right-aligned, then insert commas.
		// Let's create an array of runes for final formatted integer part including commas.
		// Number of commas = (intDigits-1)/3
		// Build from right.
		nCommas := (intDigits - 1) / 3
		totalIntLen := intDigits + nCommas
		_ = totalIntLen
		// Create digits padded with spaces to intDigits
		paddedDigits := fmt.Sprintf("%*s", intDigits, trimmed) // spaces on left
		// Now insert commas
		var out []rune
		digitIdx := 0 // from right
		// We need to walk paddedDigits from right to left, counting digits
		digits := []rune(paddedDigits)
		commaCount := 0
		// Build reversed
		var rev []rune
		for i := len(digits) - 1; i >= 0; i-- {
			rev = append(rev, digits[i])
			digitIdx++
			if digitIdx%3 == 0 && i != 0 {
				rev = append(rev, ',')
				commaCount++
			}
		}
		// Reverse rev to get out
		for i := len(rev) - 1; i >= 0; i-- {
			out = append(out, rev[i])
		}
		// Now Z suppression: any leading zero replaced by space, commas inside suppressed zone become spaces
		// Our out contains spaces where paddedDigits had spaces, commas, and digits.
		// Suppression: leading spaces stay spaces, leading zeros should be spaces (but we already trimmed zeros, so no leading zeros except the single "0")
		// For trimmed="0", paddedDigits = "      0" (e.g. intDigits 7), out will have spaces, commas and "0"
		// Need to turn commas that are before first non-space digit into spaces.
		// Find first digit that is not space and not comma? Actually first non-space char that is a digit (0-9)
		firstDigitPos := -1
		for i, c := range out {
			if c >= '0' && c <= '9' {
				// if c is '0' and it's the only digit and it's at end, it's significant
				// But we need to distinguish suppressed leading zeros: we already removed them, so no extra zeros to suppress.
				// So first digit found is the start of significant area.
				firstDigitPos = i
				break
			}
		}
		if firstDigitPos != -1 {
			for i := 0; i < firstDigitPos; i++ {
				if out[i] == ',' {
					out[i] = ' '
				}
			}
		}
		intFormatted = string(out)
	}
	var result string
	if scale > 0 {
		result = intFormatted + "." + fracPart
	} else {
		result = intFormatted
	}
	if neg {
		// place minus sign over last leading space? Simplified: replace first space before digit with '-'
		// Not needed for positive values in this program
		rs := []rune(result)
		for i := len(rs) - 1; i >= 0; i-- {
			if rs[i] == ' ' {
				rs[i] = '-'
				break
			}
			if rs[i] != ',' && rs[i] != '.' && rs[i] >= '0' && rs[i] <= '9' {
				continue
			}
		}
		result = string(rs)
	}
	return result
}

func parseDecimalDigits(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		s = "0"
	}
	// digits only
	n, _ := decimal.NewFromString(s)
	// Build with implied decimal
	// s is integer digits, value = n *10^-scale
	d := decimal.NewFromBigInt(n.BigInt(), -scale)
	return d
}

func readPara() {
	if empScanner.Scan() {
		line := empScanner.Text()
		if len(line) < 17 {
			line = line + strings.Repeat(" ", 17-len(line))
		}
		if len(line) > 17 {
			line = line[:17]
		}
		empRec.ErId = line[0:5]
		empRec.ErDept = line[5:8]
		empRec.ErHours = parseDecimalDigits(line[8:12], 1)
		empRec.ErRate = parseDecimalDigits(line[12:17], 2)
		inputDone = false
		WsEofFlag = "N"
	} else {
		inputDone = true
		WsEofFlag = "Y"
	}
}

func processPara() {
	if WsFirstFlag == "Y" {
		WsPrevDept = empRec.ErDept
		WsFirstFlag = "N"
	} else {
		if empRec.ErDept != WsPrevDept {
			deptBreakPara()
			WsPrevDept = empRec.ErDept
		}
	}
	payPara()
	readPara()
}

func payPara() {
	if empRec.ErHours.GreaterThan(decimal.NewFromInt(40)) {
		WsRegHours = decimal.NewFromInt(40)
		WsOtHours = empRec.ErHours.Sub(decimal.NewFromInt(40))
	} else {
		WsRegHours = empRec.ErHours
		WsOtHours = decimal.NewFromInt(0)
	}
	WsRegHours = truncDecimal(WsRegHours, 1)
	WsOtHours = truncDecimal(WsOtHours, 1)

	// COMPUTE WS-GROSS ROUNDED = WS-REG-HOURS * ER-RATE + WS-OT-HOURS * ER-RATE * 1.5
	oneAndHalf := decimal.NewFromFloat(1.5)
	raw := WsRegHours.Mul(empRec.ErRate).Add(WsOtHours.Mul(empRec.ErRate).Mul(oneAndHalf))
	rounded := raw.Round(2)
	// Store with truncation and low-order digit retention (PIC 9(7)V99 -> 7 int digits)
	roundedTrunc := truncDecimal(rounded, 2)
	// Simulate storage overflow: keep low-order digits
	WsGross = storeDecimal(roundedTrunc, 7, 2)

	WsDeptTotal = WsDeptTotal.Add(WsGross)
	WsDeptCount++
	WsGrandTotal = WsGrandTotal.Add(WsGross)
	WsGrandCount++

	WsHoursEd = formatNumericEdited(empRec.ErHours, 3, 1, false)
	WsRateEd = formatNumericEdited(empRec.ErRate, 3, 2, false)
	WsGrossEd = formatNumericEdited(WsGross, 7, 2, true)

	fmt.Printf("%s %s %s %s %s\n", empRec.ErId, empRec.ErDept, WsHoursEd, WsRateEd, WsGrossEd)
}

func storeDecimal(d decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// Truncate already done, now overflow handling: keep low-order digits that fit
	// Extract integer part and fraction
	s := d.StringFixed(scale)
	parts := strings.Split(s, ".")
	intPart := parts[0]
	fracPart := ""
	if len(parts) > 1 {
		fracPart = parts[1]
	}
	neg := false
	if strings.HasPrefix(intPart, "-") {
		neg = true
		intPart = intPart[1:]
	}
	if len(intPart) > intDigits {
		intPart = intPart[len(intPart)-intDigits:]
	}
	newStr := intPart
	if scale > 0 {
		newStr = newStr + "." + fracPart
	}
	res, _ := decimal.NewFromString(newStr)
	if neg {
		res = res.Neg()
	}
	// Ensure scale
	res = truncDecimal(res, scale)
	return res
}

func deptBreakPara() {
	WsDeptEd = formatNumericEdited(WsDeptTotal, 7, 2, true)
	// WS-DEPT-ED is PIC ZZZ,ZZZ,ZZ9.99 len 14 -> 7 int digits +2 commas =9 + dot+2 =12? Actually 14 includes...
	// Our formatter with 7 int digits gives len 12 (9+1+2). Need width 14, so need intDigits=9? But spec says 9? Let's check: WS-DEPT-ED ZZZ,ZZZ,ZZ9.99 has 9 digit positions.
	// However WS-DEPT-TOTAL is 9(9)V99, so dept total can be up to 9 digits, edited field also 9 digits.
	// So use 9 digits for dept/grand? Let's follow declaration: WS-DEPT-ED should be 9 digits.
	// But GO declarations derived says WS-DEPT-ED len 14 -> that matches 9 digits +2 commas +1 dot +2 decimals =14
	// So we should use 9 digits for dept/grand.
	// Recalculate with 9 digits if needed: currently we used 7 for dept. Correct to 9.
	WsDeptEd = formatNumericEdited(WsDeptTotal, 9, 2, true)
	// WS-DEPT-COUNT PIC 9(3) prints as integer without editing: zero-padded to 3? But DISPLAY prints numeric as per picture?
	// COBOL DISPLAY of PIC 9(3) prints as digits (maybe without leading zeros? Actually unedited prints as is with leading zeros? spec says zero-padded)
	// Use 3-digit zero padded
	cntStr := fmt.Sprintf("%03d", WsDeptCount)
	fmt.Printf("  DEPT %s EMPLOYEES: %s TOTAL: %s\n", WsPrevDept, cntStr, WsDeptEd)
	WsDeptTotal = decimal.NewFromInt(0)
	WsDeptCount = 0
}

func grandPara() {
	WsGrandEd = formatNumericEdited(WsGrandTotal, 10, 2, true)
	cntStr := fmt.Sprintf("%05d", WsGrandCount)
	fmt.Printf("GRAND TOTAL (%s): %s\n", cntStr, WsGrandEd)
}

func main() {
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevDept = strings.Repeat(" ", 3)
	WsRegHours = decimal.NewFromInt(0)
	WsOtHours = decimal.NewFromInt(0)
	WsGross = decimal.NewFromInt(0)
	WsDeptTotal = decimal.NewFromInt(0)
	WsGrandTotal = decimal.NewFromInt(0)

	var err error
	empFile, err = os.Open("input.dat")
	if err != nil {
		// If no file, treat as empty
		empFile = nil
		empScanner = bufio.NewScanner(strings.NewReader(""))
	} else {
		defer empFile.Close()
		empScanner = bufio.NewScanner(empFile)
		empScanner.Split(bufio.ScanLines)
	}

	// MAIN-PARA
	readPara()
