	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct {
	ErId    string
	ErDept  string
	ErHours decimal.Decimal
	ErRate  decimal.Decimal
}

var WsEofFlag string
var WsFirstFlag string
var WsPrevDept string
var WsRegHours decimal.Decimal
var WsOtHours decimal.Decimal
var WsGross decimal.Decimal
var WsDeptTotal decimal.Decimal
var WsDeptCount int64
var WsGrandTotal decimal.Decimal
var WsGrandCount int64
var WsHoursEd string
var WsRateEd string
var WsGrossEd string
var WsDeptEd string
var WsGrandEd string

var empRec EmpRec
var empFile *os.File
var empScanner *bufio.Scanner
var inputDone bool

func truncDecimal(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Truncate(scale)
}

func formatNumericEdited(d decimal.Decimal, intDigits int, scale int, withCommas bool) string {
	d = truncDecimal(d, int32(scale))
	neg := d.IsNegative()
	if neg {
		d = d.Neg()
	}
	s := d.StringFixed(int32(scale))
	parts := strings.Split(s, ".")
	intPart := "0"
	fracPart := ""
	if len(parts) == 1 {
		intPart = parts[0]
	} else {
		intPart = parts[0]
		fracPart = parts[1]
	}
	if len(intPart) > intDigits {
		intPart = intPart[len(intPart)-intDigits:]
	}
	intStrNoPad := intPart
	trimmed := strings.TrimLeft(intStrNoPad, "0")
	if trimmed == "" {
		trimmed = "0"
	}
	intFormatted := fmt.Sprintf("%*s", intDigits, trimmed)
	if withCommas {
		paddedDigits := fmt.Sprintf("%*s", intDigits, trimmed)
		var rev []rune
		digits := []rune(paddedDigits)
		for i := len(digits) - 1; i >= 0; i-- {
			rev = append(rev, digits[i])
			if (len(digits)-i)%3 == 0 && i != 0 {
				rev = append(rev, ',')
			}
		}
		var out []rune
		for i := len(rev) - 1; i >= 0; i-- {
			out = append(out, rev[i])
		}
		firstDigitPos := -1
		for i, c := range out {
			if c >= '0' && c <= '9' {
				firstDigitPos = i
				break
			}
		}
		if firstDigitPos != -1 {
			for i := 0; i < firstDigitPos; i++ {
				if out[i] == ',' {
					out[i] = ' '
				}
			}
		}
		intFormatted = string(out)
	}
	var result string
	if scale > 0 {
		result = intFormatted + "." + fracPart
	} else {
		result = intFormatted
	}
	if neg {
		rs := []rune(result)
		for i := len(rs) - 1; i >= 0; i-- {
			if rs[i] == ' ' {
				rs[i] = '-'
				break
			}
		}
		result = string(rs)
	}
	return result
}

func parseDecimalDigits(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		s = "0"
	}
	n, _ := decimal.NewFromString(s)
	d := decimal.NewFromBigInt(n.BigInt(), -scale)
	return d
}

func readPara() {
	if empScanner.Scan() {
		line := empScanner.Text()
		if len(line) < 17 {
			line = line + strings.Repeat(" ", 17-len(line))
		}
		if len(line) > 17 {
			line = line[:17]
		}
		empRec.ErId = line[0:5]
		empRec.ErDept = line[5:8]
		empRec.ErHours = parseDecimalDigits(line[8:12], 1)
		empRec.ErRate = parseDecimalDigits(line[12:17], 2)
		inputDone = false
		WsEofFlag = "N"
	} else {
		inputDone = true
		WsEofFlag = "Y"
	}
}

func processPara() {
	if WsFirstFlag == "Y" {
		WsPrevDept = empRec.ErDept
		WsFirstFlag = "N"
	} else {
		if empRec.ErDept != WsPrevDept {
			deptBreakPara()
			WsPrevDept = empRec.ErDept
		}
	}
	payPara()
	readPara()
}

func payPara() {
	if empRec.ErHours.GreaterThan(decimal.NewFromInt(40)) {
		WsRegHours = decimal.NewFromInt(40)
		WsOtHours = empRec.ErHours.Sub(decimal.NewFromInt(40))
	} else {
		WsRegHours = empRec.ErHours
		WsOtHours = decimal.NewFromInt(0)
	}
	WsRegHours = truncDecimal(WsRegHours, 1)
	WsOtHours = truncDecimal(WsOtHours, 1)

	oneAndHalf := decimal.NewFromFloat(1.5)
	raw := WsRegHours.Mul(empRec.ErRate).Add(WsOtHours.Mul(empRec.ErRate).Mul(oneAndHalf))
	rounded := raw.Round(2)
	roundedTrunc := truncDecimal(rounded, 2)
	WsGross = storeDecimal(roundedTrunc, 7, 2)

	WsDeptTotal = WsDeptTotal.Add(WsGross)
	WsDeptCount++
	WsGrandTotal = WsGrandTotal.Add(WsGross)
	WsGrandCount++

	WsHoursEd = formatNumericEdited(empRec.ErHours, 3, 1, false)
	WsRateEd = formatNumericEdited(empRec.ErRate, 3, 2, false)
	WsGrossEd = formatNumericEdited(WsGross, 7, 2, true)

	fmt.Printf("%s %s %s %s %s\n", empRec.ErId, empRec.ErDept, WsHoursEd, WsRateEd, WsGrossEd)
}

func storeDecimal(d decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	s := d.StringFixed(scale)
	parts := strings.Split(s, ".")
	intPart := parts[0]
	fracPart := ""
	if len(parts) > 1 {
		fracPart = parts[1]
	}
	neg := false
	if strings.HasPrefix(intPart, "-") {
		neg = true
		intPart = intPart[1:]
	}
	if len(intPart) > intDigits {
		intPart = intPart[len(intPart)-intDigits:]
	}
	newStr := intPart
	if scale > 0 {
		newStr = newStr + "." + fracPart
	}
	res, _ := decimal.NewFromString(newStr)
	if neg {
		res = res.Neg()
	}
	res = truncDecimal(res, scale)
	return res
}

func deptBreakPara() {
	WsDeptEd = formatNumericEdited(WsDeptTotal, 9, 2, true)
	cntStr := fmt.Sprintf("%03d", WsDeptCount)
	fmt.Printf("  DEPT %s EMPLOYEES: %s TOTAL: %s\n", WsPrevDept, cntStr, WsDeptEd)
	WsDeptTotal = decimal.NewFromInt(0)
	WsDeptCount = 0
}

func grandPara() {
	WsGrandEd = formatNumericEdited(WsGrandTotal, 11, 2, true)
	cntStr := fmt.Sprintf("%05d", WsGrandCount)
	fmt.Printf("GRAND TOTAL (%s): %s\n", cntStr, WsGrandEd)
}

func main() {
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevDept = strings.Repeat(" ", 3)
	WsRegHours = decimal.NewFromInt(0)
	WsOtHours = decimal.NewFromInt(0)
	WsGross = decimal.NewFromInt(0)
	WsDeptTotal = decimal.NewFromInt(0)
	WsGrandTotal = decimal.NewFromInt(0)

	var err error
	empFile, err = os.Open("input.dat")
	if err != nil {
		empFile = nil
		empScanner = bufio.NewScanner(strings.NewReader(""))
	} else {
		defer empFile.Close()
		empScanner = bufio.NewScanner(empFile)
		empScanner.Split(bufio.ScanLines)
	}

	readPara()
	for !inputDone {
		processPara()
	}
	if WsFirstFlag != "Y" {
		deptBreakPara()
	}
	grandPara()
}
